entries[23799] = { ["name"] = "Schematic: Adamantite Rifle", ["text"] = "Requires Engineering (350)\nUse: Teaches you how to make an Adamantite Rifle.\nSell Price:\nAdamantite Rifle\nBinds when equipped\nRanged Gun\n173 - 322 Damage Speed 3.00\n(82.50 damage per second)\n+12 Agility\n+17 Stamina\nDurability 65 / 65\nRequires Level 69\nSell Price:\nRequires Fel Iron Casing (3), Adamantite Frame (2), Handful of Fel Iron Bolts (4)" }
entries[23800] = { ["name"] = "Schematic: Felsteel Boomstick", ["text"] = "Binds when picked up\nRequires Engineering (360)\nUse: Teaches you how to make a Felsteel Boomstick.\nSell Price:\nFelsteel Boomstick\nBinds when equipped\nRanged Gun\n145 - 270 Damage Speed 2.40\n(86.46 damage per second)\n+12 Stamina\nDurability 75 / 75\nRequires Level 70\nEquip: Improves critical strike rating by 13.\nSell Price:\nRequires Hardened Adamantite Tube , Felsteel Stabilizer (4), Handful of Fel Iron Bolts (4)" }
