entries[23802] = { ["name"] = "Schematic: Ornate Khorium Rifle", ["text"] = "Requires Engineering (375)\nUse: Teaches you how to make an Ornate Khorium Rifle.\nSell Price:\nOrnate Khorium Rifle\nBinds when equipped\nRanged Gun\n202 - 376 Damage Speed 3.10\n(93.23 damage per second)\n+14 Agility\nDurability 75 / 75\nRequires Level 70\nEquip: Improves hit rating by 13.\nSell Price:\nRequires Hardened Adamantite Tube (2), Khorium Bar (12), Handful of Fel Iron Bolts (4), Noble Topaz (2)" }
