entries[23804] = { ["name"] = "Schematic: Power Amplification Goggles", ["text"] = "Requires Engineering (340)\nUse: Teaches you how to make Power Amplification Goggles.\nSell Price:\nPower Amplification Goggles\nBinds when equipped\nHead Cloth\n200 Armor\n+46 Stamina\n+31 Intellect\nDurability 80 / 80\nRequires Engineering (340)\nEquip: Improves critical strike rating by 31.\nSell Price:\nRequires Heavy Knothide Leather (4), Flame Spessarite (2), Arcane Dust (8)" }
entries[23805] = { ["name"] = "Schematic: Ultra-Spectropic Detection Goggles", ["text"] = "Requires Engineering (350)\nUse: Teaches you how to make Ultra-Spectropic Detection Goggles.\nSell Price:\nUltra-Spectropic Detection Goggles\nBinds when equipped\nHead Cloth\n295 Armor\n+36 Stamina\nDurability 80 / 80\nRequires Engineering (350)\nEquip: Improves critical strike rating by 24.\nEquip: Improves hit rating by 24.\nEquip: Improves your resilience rating by 24.\nEquip: Improves haste rating by 24.\nUse: Allows you to look far into the distance.\nSell Price:\nRequires Heavy Knothide Leather (4), Khorium Bar (2), Deep Peridot (2), Small Prismatic Shard (2)" }
entries[23806] = { ["name"] = "Schematic: Hyper-Vision Goggles", ["text"] = "Binds when picked up\nRequires Engineering (360)\nUse: Teaches you how to make Hyper-Vision Goggles.\nSell Price:\nHyper-Vision Goggles\nBinds when equipped\nHead Leather\n414 Armor\n+42 Agility\nDurability 80 / 80\nRequires Engineering (360)\nEquip: Improves hit rating by 23.\nUse: Increases your stealth detection for 15 sec. (2 Min Cooldown)\nSell Price:\nRequires Heavy Knothide Leather (4), Khorium Bar (2), Nightseye (2), Large Prismatic Shard (2)" }
entries[23807] = { ["name"] = "Schematic: Adamantite Scope", ["text"] = "Requires Engineering (335)\nUse: Teaches you how to make an Adamantite Scope.\nSell Price:\nAdamantite Scope\nRequires Level 55\nUse: Attaches a permanent scope to a bow or gun that increases its damage by 10.\n\nAttaching this scope to a ranged weapon causes it to become soulbound.\nSell Price:\nRequires Adamantite Bar (8), Golden Draenite (2)" }
